"""Tests for `tabula dedupe`, all through `python -m tabula`."""
import json, os, subprocess, sys, tempfile, unittest

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')

T = 'name,city,qty\nann,Leeds,1\nbob,York,2\nann,Leeds,3\ncy,Leeds,4\nbob,Hull,5\nann,York,6\n'
FILES = {'t.csv': T}


class DedupeTests(unittest.TestCase):
    def run_cli(self, *argv, files=None):
        with tempfile.TemporaryDirectory() as d:
            for k, v in (files or {}).items():
                with open(os.path.join(d, k), 'w', encoding='utf-8', newline='') as fh:
                    fh.write(v)
            p = subprocess.run([sys.executable, '-m', 'tabula'] + list(argv), cwd=d,
                               env=dict(os.environ, PYTHONPATH=ROOT), capture_output=True, text=True)
            return p.returncode, p.stdout, p.stderr

    def check(self, argv, rc, out, err=None, files=None):
        got_rc, got_out, got_err = self.run_cli(*argv, files=FILES if files is None else files)
        self.assertEqual((got_rc, got_out), (rc, out or ''), got_err)
        self.assertEqual(bool(got_err), rc != 0)
        if err is not None:
            self.assertEqual(got_err, 'tabula: %s\n' % err)

    def test_keep_first_default_text(self):
        self.check(['dedupe', 't.csv', 'name'], 0, 'name  city   qty\nann   Leeds  1\nbob   York   2\ncy    Leeds  4\n')

    def test_keep_first_and_last_both_spellings_anywhere(self):
        first = 'name,city,qty\nann,Leeds,1\nbob,York,2\ncy,Leeds,4\n'
        last = 'name,city,qty\ncy,Leeds,4\nbob,Hull,5\nann,York,6\n'
        for opt in (['--keep', 'first'], ['--keep=first']):
            self.check(['--format=csv'] + opt + ['dedupe', 't.csv', 'name'], 0, first)
            self.check(['--format=csv', 'dedupe', 't.csv', 'name'] + opt, 0, first)
        for opt in (['--keep', 'last'], ['--keep=last']):
            self.check(['--format=csv', 'dedupe'] + opt + ['t.csv', 'name'], 0, last)
            self.check(['--format=csv', 'dedupe', 't.csv', 'name'] + opt, 0, last)

    def test_survivors_keep_file_order_not_key_order(self):
        # last of 'a' (row 4) comes after last of 'b' (row 3): file order, not first-seen order
        files = {'t.csv': 'k,v\na,1\nb,2\nb,3\na,4\n'}
        self.check(['--format=csv', '--keep=last', 'dedupe', 't.csv', 'k'], 0, 'k,v\nb,3\na,4\n', files=files)
        self.check(['--format=csv', 'dedupe', 't.csv', 'k'], 0, 'k,v\na,1\nb,2\n', files=files)

    def test_several_keys_all_must_match(self):
        self.check(['--format=csv', 'dedupe', 't.csv', 'name', 'city'], 0,
                   'name,city,qty\nann,Leeds,1\nbob,York,2\ncy,Leeds,4\nbob,Hull,5\nann,York,6\n')
        self.check(['--format=csv', '--keep=last', 'dedupe', 't.csv', 'city', 'name'], 0,
                   'name,city,qty\nann,Leeds,3\ncy,Leeds,4\nbob,Hull,5\nbob,York,2\nann,York,6\n'.replace(
                       'ann,Leeds,3\ncy,Leeds,4\nbob,Hull,5\nbob,York,2\nann,York,6',
                       'bob,York,2\nann,Leeds,3\ncy,Leeds,4\nbob,Hull,5\nann,York,6'))

    def test_same_key_twice_is_fine(self):
        self.check(['--format=csv', 'dedupe', 't.csv', 'name', 'name'], 0, 'name,city,qty\nann,Leeds,1\nbob,York,2\ncy,Leeds,4\n')

    def test_exact_text_equality(self):
        files = {'t.csv': 'k,v\na,1\nA,2\n1,3\n1.0,4\n 1,5\n,6\n,7\n1,8\n'}
        self.check(['--format=csv', 'dedupe', 't.csv', 'k'], 0, 'k,v\na,1\nA,2\n1,3\n1.0,4\n 1,5\n,6\n', files=files)

    def test_json(self):
        rc, out, err = self.run_cli('--format=json', '--keep=last', 'dedupe', 't.csv', 'name', files=FILES)
        self.assertEqual((rc, err), (0, ''))
        self.assertEqual(json.loads(out), [{'name': 'cy', 'city': 'Leeds', 'qty': '4'},
                                           {'name': 'bob', 'city': 'Hull', 'qty': '5'},
                                           {'name': 'ann', 'city': 'York', 'qty': '6'}])

    def test_no_repeats_and_empty_table(self):
        self.check(['--format=csv', 'dedupe', 't.csv', 'qty'], 0, T)
        self.check(['--format=csv', 'dedupe', 't.csv', 'a'], 0, 'a,b\n', files={'t.csv': 'a,b\n'})

    def test_usage_errors_exit_2_before_file_is_read(self):
        for argv in (['dedupe'], ['dedupe', 'missing.csv'], ['dedupe', 't.csv'], ['--keep=middle', 'dedupe', 't.csv', 'name'],
                     ['dedupe', 't.csv', 'name', '--keep'], ['--keep', 'x', 'dedupe', 'missing.csv', 'name'],
                     ['dedupe', 'missing.csv', '--keep=']):
            for files in (FILES, {}):
                self.check(argv, 2, '', files=files)

    def test_usage_messages(self):
        self.check(['dedupe', 'missing.csv'], 2, '', files={})
        rc, out, err = self.run_cli('dedupe', 'missing.csv', files={})
        self.assertIn('usage: tabula dedupe FILE KEY...', err)
        rc, out, err = self.run_cli('--keep=middle', 'dedupe', 't.csv', 'name', files=FILES)
        self.assertIn("--keep must be one of first, last, got 'middle'", err)

    def test_missing_column_and_file_are_exit_1(self):
        self.check(['dedupe', 't.csv', 'name', 'zip'], 1, '', "t.csv: no column 'zip' (columns: name, city, qty)")
        self.check(['dedupe', 'nope.csv', 'name'], 1, '')

    def test_dash_value_is_a_column_name(self):
        self.check(['dedupe', 't.csv', '-x'], 1, '', "t.csv: no column '-x' (columns: name, city, qty)")

    def test_keys_are_not_numbers_so_non_numeric_is_fine(self):
        self.check(['--format=csv', 'dedupe', 't.csv', 'city', 'qty'], 0, T)

    def test_listed_in_help(self):
        rc, out, err = self.run_cli('--help', files={})
        self.assertIn('dedupe FILE KEY...', out + err)


if __name__ == '__main__':
    unittest.main()
